import './index.less'

export default () => {
    gsap.registerPlugin(ScrollTrigger);
    const isMobile = window.innerWidth <= 1024
    if(!isMobile) {
        const kvVideo = document.querySelector(".section-kv video")
        const kvBanner = document.querySelector(".section-kv picture img")
        const kvTitle = document.querySelector(".section-kv .kv-title")
        kvVideo.addEventListener("ended", function() {
            $(kvBanner).animate({ opacity: 1 }, 300);
            $(kvVideo).animate({ opacity: 0 }, 600);
            $(kvTitle).addClass("show")
        })
    } else {
        $(document.querySelector(".section-kv--mb .kv-title")).addClass("show")

        // 视频进入视口监听播放
        const scrollContentObserve = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    document.querySelectorAll(".sec-content--mb .sec-content--main .content>p").forEach((item, index) => {
                        setTimeout(() => {
                            item.classList.add("show")
                        }, index * 80);
                    })
                }
            }, {threshold: 0.4});
        });

        scrollContentObserve.observe(document.querySelector(".sec-content--mb .sec-content--main .content>p"))
    }

    if (!isMobile) {
        const kvTL = gsap.timeline().to(".section-kv", {
            opacity: 0
        })
        ScrollTrigger.create({
            trigger: '.themepoint-container',
            animation: kvTL,
            start: 'top top',
            end: 'top top',
            scrub: 0,
            // markers: true,
            ease: 'none'
        })
    }

    if (!isMobile) {
        // 地平线太阳光
        const themeTL = gsap.timeline().fromTo(".sun-light-bg", {
            scale: 0.5
        }, {
            scale: 1
        })
        ScrollTrigger.create({
            trigger: '.themepoint-container',
            animation: themeTL,
            start: 'top top',
            end: `+240px`,
            scrub: 0.3,
            // markers: true,
            ease: 'none',
        })
    }

    if (!isMobile) {
        // 文字
        document.querySelectorAll('.years_12_container .theme-item').forEach((item, index) => {
            gsap.to(item, {
                scrollTrigger: {
                    trigger: document.querySelectorAll(".trigger-ele")[index],
                    toggleActions: "play play reverse reverse",
                    // markers: true,
                    start: `top ${window.innerHeight - 240}`,
                    end: `bottom ${window.innerHeight - 240}`,
                    onLeave: function (self) {
                        item.classList.remove("show")
                        item.classList.add("hide")

                        if(index === document.querySelectorAll('.years_12_container .theme-item').length - 1) {
                            item.classList.remove("hide")
                            item.classList.add("show")
                        }
                    },
                    onLeaveBack: function(self) {
                        if(index === 0) {
                            item.classList.remove("hide")
                            item.classList.add("show")
                        }
                    },
                    onToggle: function (self) {
                        if (self.isActive) {
                            item.classList.remove("hide")
                            item.classList.add("show")
                        } else {
                            item.classList.remove("show")
                            item.classList.remove("hide")
                        }
                    }
                },
            })
        })
    }

    if (!isMobile && document.querySelector(".years_12_container .brand-pro .sticky-viewport")) {
        // 品牌
        const brandContainerRec = document.querySelector(".years_12_container .brand-pro .sticky-viewport")
            .getBoundingClientRect()
        const brandMdRec = document.querySelector(".content-middle--top").getBoundingClientRect()
        const scaleX = brandContainerRec.width / brandMdRec.width
        const scaleY = brandContainerRec.height / brandMdRec.height
        gsap.set(".content-middle--top", {
            scaleX,
            scaleY,
        });
        gsap.set(".stragger-item", {
            opacity: 0,
            y: 60,
        });
        gsap.set(".content-middle--top", {
            y: document.querySelector(".years_12_container .brand-pro .sticky-viewport").getBoundingClientRect()
                .top - document.querySelector(".content-middle--top").getBoundingClientRect().top
        });
        const brandTL = gsap.timeline().to(".content-middle--top", {
            y: 0,
            scaleX: 1,
            scaleY: 1
        })
        const grid = [2, 4] //[rows, columns]
        const gridTween = gsap.to(".stragger-item", {
            duration: 0.24,
            opacity: 1,
            y: 0,
            ease: "power1.inOut",
            stagger: {
                amount: 0.6,
                grid: grid,
                from: "random"
            },
            paused: true
        });
        ScrollTrigger.create({
            trigger: '.brand-pro',
            animation: brandTL,
            start: 'top top',
            end: '+=250',
            scrub: 0.5,
            // markers: true,
            ease: 'none',
            onUpdate: function (self) {
                var progress = self.progress.toFixed(2);
                if (progress > 0.1) {
                    document.querySelector(".content-middle--top .sunline").classList.add("hide")
                } else {
                    document.querySelector(".content-middle--top .sunline").classList.remove("hide")
                }
            },
            onLeave: function (self) {
                self.progress && gridTween.play()
            },
            onEnterBack: function () {
                gridTween.reverse()
            }
        })

        // 奖项
        document.querySelectorAll(".awards-animate").forEach(item => {
            gsap.to(item, {
                scrollTrigger: {
                    trigger: document.querySelector(".awards-container"),
                    toggleActions: "play play reverse reverse",
                    // markers: true,
                    start: `center bottom`,
                    end: `bottom bottom`,
                },
                opacity: 1,
                y: 0,
                scrub: 0.2,
            })
        })
    }

    // 深度礼盒
    let gift_splits = ``
    const char_len = document.querySelector(".fix-gift .title-primary").innerText.split('').length
    document.querySelector(".fix-gift .title-primary").innerText.split('').forEach(char => {
        gift_splits += `<span>${char}</span>`
    })
    document.querySelector(".fix-gift .title-primary").innerHTML = gift_splits
    const gift_anchors = isMobile ? document.querySelectorAll(".gift-anchor--mb") : document.querySelectorAll(".gift-anchor")
    gift_anchors.forEach((item, index) => {
        const gift_chars = document.querySelectorAll(".fix-gift .title-primary span")
        gift_chars[index] && gsap.to(gift_chars[index], {
            scrollTrigger: {
                trigger: item,
                toggleActions: "play play reverse reverse",
                start: `top top`,
                end: `+=10px`,
                onLeave: function (self) {
                    gift_chars[index].classList.add("active")
                    if(index === char_len - 1) {
                        document.querySelector(".gift-icon").classList.add("active")
                        document.querySelector(".fix-gift").classList.add("open")
                    } else {
                        document.querySelector(".gift-icon").classList.remove("active")
                        document.querySelector(".fix-gift").classList.remove("open")
                    }
                },
                onLeaveBack: function () {
                    gift_chars[index].classList.remove("active")
                    document.querySelector(".gift-icon").classList.remove("active")
                    document.querySelector(".fix-gift").classList.remove("open")
                },
                onEnter: function () {
                    gift_chars[index].classList.add("active")
                    if(index === char_len - 1) {
                        document.querySelector(".gift-icon").classList.add("active")
                        document.querySelector(".fix-gift").classList.add("open")
                    } else {
                        document.querySelector(".gift-icon").classList.remove("active")
                        document.querySelector(".fix-gift").classList.remove("open")
                    }
                }
            },
        })
    })

    if(isMobile) {
        new Swiper(".awards-container--mb .swiper", {
            slidesPerView: "auto",
            spaceBetween: 10,
            pagination: {
                el: ".awards-container--mb .swiper-pagination",
                type: "progressbar",
            },
        });
    }

    function downloadPdf(pdfUrl) {
        fetch(pdfUrl)
            .then(response => response.blob())
            .then(blob => {
            var url = window.URL.createObjectURL(blob);
            var a = document.createElement("a");
            a.href = url;
            try {
                const _list = pdfUrl.split(".pdf")[0].split("/")
                a.download = _list[_list.length-1]
            } catch (error) {
                a.download = "downloaded.pdf";  
            }
            document.body.appendChild(a);
            a.click();

            window.URL.revokeObjectURL(url);
            document.body.removeChild(a);
            })
            .catch(error => {
            console.error("Failed to download the PDF file: ", error);
            });
    }
    $("img[data-pdf]").click(function() {
        const pdfUrl = $(this).attr("data-pdf")
        if(!pdfUrl) return

        downloadPdf(pdfUrl)
    })
}