import './index.less'
import jkyNav from '../../common/components/jky-nav'
import animateMain from "./sections/jky-12th-animate/index";
import {Scene} from "./sections/jky-12th-scene/index.js";
import { MemberShip } from './sections/jky-12th-membership/index'
import { Points } from './sections/jky-12th-points/index'
import { CommentForm } from './sections/jky-12th-form/index'
import { Comments } from './sections/jky-12th-comments/index'

$(document).ready(function() {
   animateMain()
   jkyNav()
   new Scene({el: '.jky-12th-scene'})
   new MemberShip()
   new Points('.jky-12th-points')
   new CommentForm({el: '.jky-12th-form'})
   new Comments()

   // 渐变出现
   const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
          if (entry.isIntersecting) {
            // 元素进入视窗,触发动画
            entry.target.classList.add('jky-up-animation');
          }
      });
  });

  // 开始观察目标元素
  const slideups = document.querySelectorAll('.jky-up')
  if (slideups && slideups.length) {
      slideups.forEach(item => {
          observer.observe(item); 
      })
  }
})
