import { getCommentList } from '@utils/api.js'
import { dateFormat } from '@utils/index.js'
import dayjs from "dayjs";

export class Comments {
    constructor() {
        this.page = 1
        this.swiper = null
        this.flag = true
        this.compTheme = $('.jky-12th-comments').data('theme') || 'default'
        this.avatar = $('.jky-12th-comments').data('avatar')
        this.status = $('.jky-12th-comments').data('status')
        this.title = $('.jky-12th-comments').data('title')
        this.favorite = $('.jky-12th-comments').data('favorite')
        this.hbid = $('.jky-12th-comments').data('hbid') || ''
        this.view_more = $('.jky-12th-comments').data('view_more') || ''
        this.init()
    }
    async init() {
        const that = this
        if ($('.jky-12th-comments').length == 0) return false
        this.initSwiper()
        this.getData()

        // 点击
        $('.jky-12th-comments').on('click', '.comment-link-a', function () {
            const gaParams = {
                module: that.title,
                button_name: $(this).text(),
                link: $(this).attr('href')
            }
            that.handleGAEvent(gaParams)
        })
        // view more 点击
        $('.jky-12th-comments').on('click', '.view-more', function () {
            $(this).hide()
            $(this).siblings('.comment-text').css({ 'display': 'block' })
        })
    }
    initSwiper() {
        const that = this
        this.swiper = new Swiper(".swiper-comments", {
            slidesPerView: this.compTheme == 'default' ? 1.1 : window.innerWidth >= 1024 ? 2 : 1,
            spaceBetween: this.compTheme == 'default' ? 12 : window.innerWidth >= 1024 ? 32 : 0,
            initialSlide: 0,
            navigation: {
                nextEl: ".comments-next",
                prevEl: ".comments-prev",
            },
            pagination: {
                el: ".swiper-pagination",
                clickable: true,
            },
            breakpoints: {
                1024: {
                    spaceBetween: 32,
                    slidesPerView: 2,
                },
            },
            on: {
                slideChange: function () {
                    if (this.isEnd && that.flag) {
                        that.page++
                        that.getData()
                    }
                },
                slidePrevTransitionEnd: function () {
                    const gaParams = {
                        module: $('.jky-12th-comments .title').text(),
                        button_name: 'left',
                        status: that.status
                    }
                    that.handleGAEvent(gaParams)
                },
                slideNextTransitionEnd: function () {
                    const gaParams = {
                        module: $('.jky-12th-comments .title').text(),
                        button_name: 'right',
                        status: that.status
                    }
                    that.handleGAEvent(gaParams)
                },
            }
        });
    }
    async getData() {
        const that = this
        const params = {
            page: this.page,
            limit: 3,
            activeNum: this.hbid
        }
        try {
            const { data } = await getCommentList(params)
            const count = data.count || 0
            this.flag = Math.ceil(count / params.limit) > params.page
            const list = data.data || []
            const cr = pageInfo.cr
            list.forEach(item => {
                let linkhtml = ''
                let contentHtml = ''
                let dialogHtml = ''
                if (that.compTheme == 'default') {
                    linkhtml = item.goodsUrl ? `
                        <span class="favorite">${this.favorite}</span>
                        <a class="comment-link-a" href="${item.goodsUrl}" >${item.originTitle}</a>` 
                        : ``

                    contentHtml = `
                        <div class="infos">
                            <div class="content">
                                <div class="user">
                                    <img class="avatar" src="${that.avatar}" alt="Avatar">
                                    <span>${item.name}</span>
                                </div>
                                <div class="date">
                                    <span class="create-at"> ${dayjs(item.createdAt).format(dateFormat(cr))}</span>
                                    ${item.tagName ? `<span class="label">${item.tagName}</span>` : ''}
                                </div>
                            </div>
                            <div class="content-info">
                                <div class="comment">
                                    <div class="comment-text">${item.comment}</div>
                                    <div class="view-more">
                                        <span class="little">... </span>
                                        <span class="text"> ${that.view_more}</span>
                                        <svg t="1726812898766" class="icon" viewBox="0 0 1024 1024" version="1.1" xmlns="http://www.w3.org/2000/svg" p-id="2796" width="14" height="14"><path d="M512 818.07039273L1000.12067353 329.94971923l-101.69180708-111.86098796L512 604.51759771 125.57113355 218.08873127 13.71014559 329.94971923z" fill="var(--jds-color-primary)" p-id="2797"></path></svg></div>
                                </div>
                                ${item.fileUrl ? `
                                    <div class="image">
                                        <img src="${item.fileUrl}">
                                    </div>
                                `: ''}
                            </div>
                            <div class="comment-link" >
                                ${linkhtml}
                            </div>
                        </div>
                    `
                } else {
                    const userInfoHtml = `
                        <div class="user-info flex items-center mt-3 gap-3">
                            <img class="avatar w-5 h-5 lg:w-8 lg:h-8" src="${that.avatar}" alt="Avatar">
                            <div class="user-info-content">
                                <p class="name !text-[13px] lg:!text-base !mb-0">${item.name}</p>
                                <p class="create-at !text-[12px] lg:!text-xs">${dayjs(item.createdAt).format(dateFormat(cr))}</p>
                            </div>
                        </div>
                    `
                    const imgHtml = item.fileUrl ? `
                                    <div class="image">
                                        <img src="${item.fileUrl}">
                                    </div>
                                `: ''
                    contentHtml = `
                        <div class="content-img flex flex-wrap justify-center w-[6.4375rem] h-[6.4375rem] lg:w-[14.75rem] lg:h-[14.75rem]">
                            <div class="img-box rounded-full bg-[#fff] p-3 w-[6.4375rem] h-[6.4375rem] lg:w-[14.75rem] lg:h-[14.75rem]"><img class="w-full h-full object-cover rounded-full" src="${item.fileUrl}"></div>
                            <img class="stars w-[4.6875rem] lg:w-[10.75rem] -mt-5 lg:-mt-10" src="https://cdn.shopify.com/s/files/1/0550/0524/9633/files/icon-stars.png?v=1769245527">
                        </div>
                        <div class="content-info relative">
                            <svg class="icon-union block -ml-[1.6875rem] lg:-ml-[3.75rem] w-6 h-5 lg:w-12 lg:h-10" width="48" height="40" viewBox="0 0 48 40" fill="none" xmlns="http://www.w3.org/2000/svg">
                                <path d="M16.431 -9.13522e-06L20.2457 7.62953C13.3987 10.8574 9.97519 15.1613 9.87738 21.7148C10.2686 21.617 10.6599 21.617 11.0512 21.617C15.9419 21.617 19.9523 24.9427 19.9523 30.2247C19.9523 35.9958 16.1375 39.7127 11.0512 39.7127C3.71506 39.7127 -0.00189854 34.1373 -0.00189854 24.5515C-0.00189854 13.7919 5.37791 5.47761 16.431 -9.13522e-06ZM43.8191 -9.13522e-06L47.6338 7.62953C40.7868 10.8574 37.3633 15.1613 37.2655 21.7148C37.6567 21.617 38.048 21.617 38.4393 21.617C43.33 21.617 47.3404 24.9427 47.3404 30.2247C47.3404 35.9958 43.5256 39.7127 38.4393 39.7127C31.1032 39.7127 27.3862 34.1373 27.3862 24.5515C27.3862 13.7919 32.766 5.47761 43.8191 -9.13522e-06Z" fill="#EC76A2"/>
                            </svg>
                            <div class="comment">
                                <div class="text-ellipsis-3 mb-1 lg:mb-3">${item.comment}</div>
                                <jds-button class="view-more-btn" data-dialog-id="dialog-${item.id}" size="${window.innerWidth >= 1024 ? 'medium' : 'small'}" kind="custom" style="--jds-btn-custom-color: #EC76A2">${that.view_more}</jds-button>
                                ${userInfoHtml}
                            </div>
                        </div> 
                        `
                        
                        dialogHtml = `
                            <jds-dialog class="comment-dialog" caption="&nbsp;" id="dialog-${item.id}" class="default" size="large" showclose="true" disablebodyscroll="true">
                                <div class="jds-rte font-regular">
                                    ${item.comment}
                                    ${imgHtml}
                                    <div class="user-info flex items-center mt-3 gap-3">
                                        <img class="avatar w-6 h-6 lg:w-8 lg:h-8" src="${that.avatar}" alt="Avatar">
                                        <div class="user-info-content">
                                            <p class="name !text-[13px] lg:!text-base !mb-0">${item.name}</p>
                                            <p class="create-at !text-xs">${dayjs(item.createdAt).format(dateFormat(cr))}</p>
                                        </div>
                                    </div>
                                </div>
                            </jds-dialog>
                        `
                }

                // 加入dialog
                if(that.compTheme === 'jp-cherry'){
                    const tempDiv = document.createElement('div')
                    tempDiv.innerHTML = dialogHtml
                    document.body.appendChild(tempDiv.firstElementChild)
                }

                const html = `
                    <div class="swiper-slide">
                        ${contentHtml}
                    </div>
                `
                $('#swiper-comments-wrapper').append(html)
            })

            this.swiper.update()
            // 只对新加入的slide执行calcActualLines
            const newSlides = $('#swiper-comments-wrapper .swiper-slide').slice(-list.length)
            newSlides.each((index, slide) => {
                const container = $(slide).find('.comment-text')[0]
                this.calcLines(container)
            })

            // 绑定view more按钮点击事件
            if(that.compTheme === 'jp-cherry'){
                document.querySelectorAll('.view-more-btn').forEach(btn => {
                    btn.addEventListener('click', function () {
                        const dialogId = this.dataset.dialogId
                        document.getElementById(dialogId).setAttribute('open', 'true')
                    })  
                })
            }
        } catch (error) {
            pushErrorMessage(error.message)
        }

    }
    // 埋码
    handleGAEvent(params) {
        // 埋码
        window.dataLayer.push({ "event_parameters": null });
        window.dataLayer.push({
            event: "ga4Event",
            event_name: "section_comment_user_clicks",
            event_parameters: {
                current_page: window.location.href,
                ...params
            }
        });
    }
    // 计算实际行数
    calcActualLines() {
        const containers = document.querySelectorAll('.infos .comment .comment-text')
        if (!containers.length) return
        containers.forEach(container => () => this.calcLines(container))
    }
    calcLines(container) {
        // 获取评论区域中的图片
        const img = $(container).closest('.content-info').find('.image img')
        // 判断图片是否存在且src不为空
        if (img.length && img.attr('src')) {
            const computedStyle = window.getComputedStyle(container);
            const lineHeight = parseFloat(computedStyle.lineHeight);
            const containerHeight = parseFloat(computedStyle.height);
            // 计算最大行数
            const maxLines = Math.floor(containerHeight / lineHeight);
            // 计算实际行数
            const textLines = Math.floor(container.scrollHeight / lineHeight);
            // 如果实际行数大于最大行数，显示view more按钮
            if (textLines > maxLines) {
                $(container).siblings('.view-more').css({ 'display': 'flex' })
            } else {
                $(container).siblings('.view-more').hide()
            }
        } else {
            // 如果图片不存在，显示所有文案，隐藏view more按钮
            $(container).css({ 'display': 'block' })
            $(container).siblings('.view-more').hide()
        }
    }

}
