import { getPointAccount} from '@utils/api'
export class Points {
    constructor(el) {
        this.el = $(el)
        const id = this.el.data('id')
        $(`${el} a`).attr('data-ga-params-module', $('.membership-title .text').text())
        if(id) {
            this.init()
        }
    }
    
    async init() {
        try {
            const {data} = await getPointAccount()
            this.el.find('.real').text(data.balancePoint || 0)
        } catch (error) {
            window.postMessage(error)
        }
        

    }
}